<section class="container section search-layout"><aside class="card filter-sidebar"><h2>Filters</h2><form method="get" action="/search" class="stack-form"><label>Search <input type="search" name="q" value="<?= e($query) ?>"></label><label>Tags <input type="text" name="tags" value="<?= e(implode(', ', $filters['tags'] ?? [])) ?>" placeholder="italian, quick"></label><label>Categories <input type="text" name="categories" value="<?= e(implode(', ', $filters['categories'] ?? [])) ?>" placeholder="Dinner, Dessert"></label><label>Include ingredients <input type="text" name="include" value="<?= e(implode(', ', $filters['include_ingredients'] ?? [])) ?>"></label><label>Exclude ingredients <input type="text" name="exclude" value="<?= e(implode(', ', $filters['exclude_ingredients'] ?? [])) ?>"></label><label>Sort <select name="sort"><option value="relevance">Relevance</option><option value="latest" <?= ($filters['sort'] ?? '') === 'latest' ? 'selected' : '' ?>>Latest</option><option value="rating" <?= ($filters['sort'] ?? '') === 'rating' ? 'selected' : '' ?>>Rating</option><option value="title" <?= ($filters['sort'] ?? '') === 'title' ? 'selected' : '' ?>>Title</option></select></label><button class="button" type="submit">Apply filters</button></form></aside><div><h1>Search results</h1><p class="muted"><?= count($results) ?> recipes found</p><div class="recipe-grid"><?php foreach ($results as $recipe): ?><?php include TEMPLATES_PATH . '/partials/recipe-card.php'; ?><?php endforeach; ?></div></div></section>
